using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class FinishHud08DValidation{
const string Root="Docs/Measurements/2026-10-03-hud-08d/";
public static string Setup(){if(Application.isPlaying)throw new Exception("Edit required");Environment.SetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT",Path.GetFullPath(Root+EditorSceneManager.GetActiveScene().name+"-save"));Application.runInBackground=true;return "Isolated save root configured";}
public static string Open(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/OpenWorldSandbox.unity");return "Opened empty-base scene";}
public static string Check(){if(!Application.isPlaying)throw new Exception("Play required");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();if(h.Sandbox.Persistence!=null)h.Sandbox.Persistence.Automatic=false;h.Groups.Select(true);var a=h.BaseResources;a.Refresh();if(a.BaseCount!=0||!a.Empty.gameObject.activeSelf||a.Rows.Any(r=>r.Root.activeSelf)||a.Previous.interactable||a.Next.interactable)throw new Exception("Empty base state failed");File.WriteAllText(Root+"empty-state.json",new JObject{{"result","PASS"},{"scene","OpenWorldSandbox"},{"emptyMessage",a.Empty.text},{"baseCount",a.BaseCount}}.ToString());return "Empty state passed";}
public static string Restore(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/StartRegionSandbox.unity");Environment.SetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT",null);Application.runInBackground=false;AssetDatabase.SaveAssets();var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();File.WriteAllText(Root+"final-editor-state.json",new JObject{{"scene",EditorSceneManager.GetActiveScene().path},{"playing",Application.isPlaying},{"dirty",EditorSceneManager.GetActiveScene().isDirty},{"saveOverrideCleared",Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")==null},{"runInBackground",Application.runInBackground},{"testControlsSavedActive",h.Buttons.Where(b=>new[]{"infinite-resources","quick-day","quick-night"}.Contains(b.Id)).All(b=>b.View.gameObject.activeSelf)}}.ToString());return "Restored clean StartRegionSandbox Edit state";}
}
